import React, { useState } from 'react';
import FileUploader from '../components/FileUploader';
import Result from '../components/Result';
import axios from 'axios';

const JAVA_URL = 'http://localhost:8080/api/quizzes';

const QuizPage = () => {
    const [result, setResult] = useState(null);
    const [error, setError] = useState(null);
    const [isLoading, setIsLoading] = useState(false);

    const handleFileSuccess = async (extractedText) => {
        try {
            setIsLoading(true);
            
            // Appel à l'API de génération de quiz avec le texte extrait
            const response = await axios.post('http://localhost:8080/api/quizzes/generate', {
                content: extractedText
            });

            setResult(response.data);
        } catch (err) {
            setError(err.response?.data || "Erreur lors de la génération du quiz");
        } finally {
            setIsLoading(false);
        }
    };

    const handleError = (errorMessage) => {
        setError(errorMessage);
    };

    return (
        <div className="quiz-page">
            <h1>Générer un Quiz</h1>

            <FileUploader
                onSuccess={handleFileSuccess}
                onError={handleError}
                maxSizeMB={10}
                apiBaseUrl="http://localhost:8080"
            />

            {isLoading && (
                <div className="loading-container">
                    <p>Génération du quiz en cours...</p>
                </div>
            )}

            {error && <p className="error">{error}</p>}
            
            {result && (
                <div className="quiz-result">
                    <h2>{result.title}</h2>
                    <pre>{result.content}</pre>
                </div>
            )}
        </div>
    );
};

export default QuizPage;
